import{_ as e,o,c as n,a3 as a}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Quotations — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Quotations — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/quotations"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Quotations — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/quotations"}]]},"headers":[],"relativePath":"user-guide/quotations.md","filePath":"user-guide/quotations.md","lastUpdated":1787238031000}'),s={name:"user-guide/quotations.md"};function i(r,t,l,d,c,u){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="quotations-—-user-guide" tabindex="-1">Quotations — User Guide <a class="header-anchor" href="#quotations-—-user-guide" aria-label="Permalink to &quot;Quotations — User Guide&quot;">​</a></h1><h2 id="who-can-use-quotations" tabindex="-1">Who can use Quotations <a class="header-anchor" href="#who-can-use-quotations" aria-label="Permalink to &quot;Who can use Quotations&quot;">​</a></h2><p>Your workspace must have the <strong>Opportunities</strong> module installed, then the <strong>Quotations</strong> module (free from Marketplace — not auto-installed). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>send</code>, <code>accept</code>, <code>convert</code> as needed).</p><p>Without <strong>assign</strong>, you only see quotations assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Quotations</strong> from the sidebar (Sales). Search by title, filter by status, opportunity, or assignee, or toggle <strong>My Quotations</strong>. The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted quotation from the row menu</li><li><strong>Delete permanently</strong> requires <code>quotations.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New quotation</strong></li><li>Choose the related <strong>Opportunity</strong> (required) — this auto-fills <strong>Contact</strong>, <strong>Company</strong>, and <strong>Assignee</strong> when those are set on the opportunity (you can still change them)</li><li>Enter a title, optional contact/company link, currency, valid-until date, notes, and optional <strong>Terms &amp; conditions</strong> (rich text — headings, lists, bold/italic/underline)</li><li>Choose a shared <strong>line discount type</strong> (none, percent, or fixed) for the document, then add lines. When <strong>Products</strong> is installed, optionally <strong>select a product</strong> to auto-fill name, details (from the product description), and unit price — you can still edit those fields. Lines also include Qty, Discount value (when type is not none), Tax %, with optional rich-text <strong>Details</strong> under each row — subtotal, discount, tax, and total update automatically. Tax is applied after line discounts.</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the record page while the quotation is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Send</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A quotation starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Send</strong> (<code>draft → sent</code>) — marks the quote as sent in the CRM (does not email the customer or attach a PDF yet)</li><li><strong>Accept</strong> (<code>sent → accepted</code>) or <strong>Reject</strong> / <strong>Expire</strong> via the status action</li></ul><p>Invalid transitions (e.g. accepting directly from Draft) are rejected with a validation error.</p><h2 id="convert-to-invoice" tabindex="-1">Convert to invoice <a class="header-anchor" href="#convert-to-invoice" aria-label="Permalink to &quot;Convert to invoice&quot;">​</a></h2><p>Once a quotation is <strong>Sent</strong> or <strong>Accepted</strong> and <strong>Invoices</strong> is installed, use <strong>Convert to invoice</strong> from the record page or row menu (<code>quotations.convert</code>):</p><ul><li>Creates a new <strong>draft</strong> invoice with the same title, notes, terms &amp; conditions, currency, line discounts, contact/company, assignee, and a copy of every line item</li><li>Marks the quotation <strong>Accepted</strong> automatically if it wasn&#39;t already</li><li>The quotation record page then shows a link to the <strong>converted invoice</strong></li><li>A quotation can only be converted <strong>once</strong> — the action is hidden once any invoice already has this quotation linked (including invoices created from a linked estimate or contract)</li><li>Without Invoices installed, the action is hidden; the API returns a validation error if called directly</li></ul><h2 id="download-pdf" tabindex="-1">Download PDF <a class="header-anchor" href="#download-pdf" aria-label="Permalink to &quot;Download PDF&quot;">​</a></h2><p><strong>Download PDF</strong> is on the quotation record page and the row menu. It generates a branded PDF using your <strong>Settings → Branding</strong> button color, logo (when uploaded), and company profile — plus line items (with HTML details), discount/tax/total breakdown, memo notes, and terms &amp; conditions. Long notes and terms continue across as many pages as needed. Sending still does not email the customer.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Overview</strong> — shows the quotation memo from the create/edit <strong>Notes</strong> field (also printed on the PDF)</li><li><strong>Notes</strong> tab — internal activity notes the team adds after the quotation exists (not the same as the memo)</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, conversion, note, and delete/restore events</li></ul>',23)])])}const m=e(s,[["render",i]]);export{h as __pageData,m as default};
